begin;
create table public.verification_tasks(id uuid primary key default gen_random_uuid(),asset_id uuid unique not null references public.audio_assets(id) on delete cascade,status public.job_state not null default 'queued',attempt integer not null default 0,lease_hash text,lease_expires_at timestamptz,error text,created_at timestamptz not null default now());
alter table public.verification_tasks enable row level security;
create policy verification_read on public.verification_tasks for select to authenticated using(exists(select 1 from public.audio_assets a where a.id=asset_id and public.band_permission(a.band_id,array['owner','admin','editor']::public.band_role[])));

create function public.submit_separation(b uuid,s uuid,input uuid,job uuid,idem text) returns public.processing_jobs language plpgsql security definer set search_path=public as $$declare e public.entitlements;u public.band_usage;a public.audio_assets;c public.platform_config;j public.processing_jobs;monthly bigint;global_used bigint;reserve bigint;begin
 if not public.band_permission(b,array['owner','admin','editor']::public.band_role[]) then raise exception 'BR:Editor permission required';end if;
 select * into c from public.platform_config where id=true for update;
 select * into j from public.processing_jobs where band_id=b and idempotency_key=idem;if found then return j;end if;
 if not c.ai_enabled or c.worker_online_at is null or c.worker_online_at<now()-interval '90 seconds' then raise exception 'BR:AI processing is currently unavailable';end if;
 select * into u from public.band_usage where band_id=b for update;select * into e from public.entitlements where band_id=b;select * into a from public.audio_assets where id=input and song_id=s and band_id=b and source='original' and status<>'deleting';
 if not found or a.duration>e.ai_seconds_limit then raise exception 'BR:Input missing or exceeds AI duration allowance';end if;
 if exists(select 1 from public.processing_jobs where band_id=b and status in ('queued','processing')) then raise exception 'BR:A job is already active for this band';end if;
 select coalesce(sum(seconds),0) into monthly from public.processing_usage where band_id=b and month=date_trunc('month',now())::date and state in ('reserved','consumed');
 select coalesce(sum(seconds),0) into global_used from public.processing_usage where month=date_trunc('month',now())::date and state in ('reserved','consumed');
 if monthly+ceil(a.duration)>e.ai_monthly_seconds or global_used+ceil(a.duration)>c.monthly_ai_seconds_cap then raise exception 'BR:Processing allowance reached';end if;
 reserve=ceil(a.duration)::bigint*44100*6*4+1048576;
 if u.stored_bytes+u.reserved_bytes+reserve>e.storage_limit then raise exception 'BR:Not enough space for four lossless stems';end if;
 insert into public.processing_jobs(id,band_id,song_id,input_asset_id,created_by,idempotency_key,duration_seconds,output_reserved_bytes) values(job,b,s,input,auth.uid(),idem,ceil(a.duration),reserve) returning * into j;
 update public.band_usage set reserved_bytes=reserved_bytes+reserve where band_id=b;insert into public.processing_usage(job_id,band_id,month,seconds,state) values(job,b,date_trunc('month',now())::date,ceil(a.duration),'reserved');return j;
end$$;
create function public.retry_separation(job uuid) returns public.processing_jobs language plpgsql security definer set search_path=public as $$declare j public.processing_jobs;e public.entitlements;u public.band_usage;c public.platform_config;monthly bigint;global_used bigint;begin select * into j from public.processing_jobs where id=job for update;if not public.band_permission(j.band_id,array['owner','admin','editor']::public.band_role[]) or j.status<>'failed' or j.attempt>=j.max_attempts then raise exception 'BR:Retry unavailable';end if;if not exists(select 1 from public.audio_assets where id=j.input_asset_id and status='verified') then raise exception 'BR:Original is unavailable or invalid. Upload a decodable recording to create a new job.';end if;select * into c from public.platform_config where id=true for update;if not c.ai_enabled then raise exception 'BR:AI disabled';end if;select * into u from public.band_usage where band_id=j.band_id for update;select * into e from public.entitlements where band_id=j.band_id;if u.stored_bytes+u.reserved_bytes+j.output_reserved_bytes>e.storage_limit or exists(select 1 from public.processing_jobs where band_id=j.band_id and status in ('queued','processing')) then raise exception 'BR:Capacity or active-job limit reached';end if;select coalesce(sum(seconds),0) into monthly from public.processing_usage where band_id=j.band_id and month=date_trunc('month',now())::date and state in ('consumed','reserved');select coalesce(sum(seconds),0) into global_used from public.processing_usage where month=date_trunc('month',now())::date and state in ('consumed','reserved');if monthly+(case when exists(select 1 from public.processing_usage where job_id=job and state='consumed') then 0 else j.duration_seconds end)>e.ai_monthly_seconds or global_used+(case when exists(select 1 from public.processing_usage where job_id=job and state='consumed') then 0 else j.duration_seconds end)>c.monthly_ai_seconds_cap then raise exception 'BR:Processing allowance reached';end if;update public.processing_jobs set status='queued',error=null,lease_hash=null,updated_at=now() where id=job returning * into j;update public.band_usage set reserved_bytes=reserved_bytes+j.output_reserved_bytes where band_id=j.band_id;update public.processing_usage set state='reserved',month=date_trunc('month',now())::date where job_id=job and state='released';return j;end$$;
create function public.cancel_separation(job uuid) returns void language plpgsql security definer set search_path=public as $$declare j public.processing_jobs;begin select * into j from public.processing_jobs where id=job for update;if not public.band_permission(j.band_id,array['owner','admin','editor']::public.band_role[]) then raise exception 'BR:Permission denied';end if;if j.status not in ('queued','processing') then return;end if;update public.processing_jobs set status='canceled',lease_hash=null,updated_at=now() where id=job;update public.band_usage set reserved_bytes=greatest(0,reserved_bytes-j.output_reserved_bytes) where band_id=j.band_id;update public.processing_usage set state='released' where job_id=job and state='reserved';end$$;
create function public.claim_job(hash text) returns jsonb language plpgsql security definer set search_path=public as $$declare v public.verification_tasks;j public.processing_jobs;a public.audio_assets;begin
 update public.platform_config set worker_online_at=now() where id=true;
 select * into v from public.verification_tasks where status='queued' or status='processing' and lease_expires_at<now() and attempt<3 order by created_at for update skip locked limit 1;
 if found then update public.verification_tasks set status='processing',attempt=attempt+1,lease_hash=hash,lease_expires_at=now()+interval '5 minutes' where id=v.id;select * into a from public.audio_assets where id=v.asset_id;return jsonb_build_object('kind','verification','id',v.id,'asset',to_jsonb(a));end if;
 select p.* into j from public.processing_jobs p join public.audio_assets aa on aa.id=p.input_asset_id join public.bands b on b.id=p.band_id where (p.status='queued' or p.status='processing' and p.lease_expires_at<now()) and p.attempt<p.max_attempts and aa.status='verified' and not b.suspended and (select ai_enabled from public.platform_config where id=true) order by p.created_at for update of p skip locked limit 1;
 if found then update public.processing_jobs set status='processing',attempt=attempt+1,lease_hash=hash,lease_expires_at=now()+interval '10 minutes',updated_at=now() where id=j.id;update public.processing_usage set state='consumed' where job_id=j.id;select * into a from public.audio_assets where id=j.input_asset_id;return jsonb_build_object('kind','separation','id',j.id,'asset',to_jsonb(a),'band_id',j.band_id,'song_id',j.song_id,'max_seconds',j.duration_seconds);end if;return null;
end$$;
create function public.finish_separation(job uuid,hash text,outputs jsonb,job_error text default null) returns void language plpgsql security definer set search_path=public as $$declare j public.processing_jobs;st jsonb;total bigint;begin select * into j from public.processing_jobs where id=job for update;if j.status='completed' then return;end if;if j.status<>'processing' or j.lease_hash<>hash or j.lease_expires_at<now() then raise exception 'BR:Stale job';end if;
 if job_error is not null then update public.processing_jobs set status='failed',error=left(job_error,500),lease_hash=null,updated_at=now() where id=job;update public.band_usage set reserved_bytes=greatest(0,reserved_bytes-j.output_reserved_bytes) where band_id=j.band_id;update public.processing_usage set state='released' where job_id=job and state='reserved';return;end if;
 if jsonb_array_length(outputs)<>4 or (select count(distinct x->>'category') from jsonb_array_elements(outputs) x)<>4 then raise exception 'BR:Expected four model stems';end if;select sum((x->>'bytes')::bigint) into total from jsonb_array_elements(outputs) x;if total>j.output_reserved_bytes then raise exception 'BR:Outputs exceed reserved storage';end if;
 for st in select value from jsonb_array_elements(outputs) loop if st->>'category' not in ('vocals','drums','bass','other') or st->>'object_key' not like 'bands/'||j.band_id||'/songs/'||j.song_id||'/%' then raise exception 'BR:Invalid model output';end if;insert into public.audio_assets(id,band_id,song_id,bucket,object_key,filename,category,bytes,duration,sample_rate,source,status) values((st->>'id')::uuid,j.band_id,j.song_id,'stems',st->>'object_key',st->>'filename',st->>'category',(st->>'bytes')::bigint,(st->>'duration')::double precision,(st->>'sampleRate')::integer,'ai','verified');end loop;
 update public.band_usage set reserved_bytes=greatest(0,reserved_bytes-j.output_reserved_bytes),stored_bytes=stored_bytes+total where band_id=j.band_id;update public.processing_usage set state='consumed' where job_id=job;update public.processing_jobs set status='completed',results=outputs,error=null,lease_hash=null,updated_at=now() where id=job;
end$$;

create function public.session_mutate(code_input text,expected bigint,next_state jsonb) returns public.playback_sessions language plpgsql security definer set search_path=public as $$declare p public.playback_sessions;begin select * into p from public.playback_sessions where code=code_input for update;if not public.session_control(p.id) then raise exception 'BR:Playback control permission denied';end if;if p.revision<>expected then raise exception 'BR:Session changed, try again';end if;update public.playback_sessions set data=next_state,revision=revision+1 where id=p.id returning * into p;return p;end$$;
create function public.grant_control(session uuid,target uuid,allowed boolean) returns void language plpgsql security definer set search_path=public as $$declare p public.playback_sessions;begin select * into p from public.playback_sessions where id=session for update;if p.leader_id<>auth.uid() or not public.session_access(session) then raise exception 'BR:Only the session leader manages controllers';end if;if not exists(select 1 from public.band_memberships where band_id=p.band_id and user_id=target) then raise exception 'BR:Choose a band member';end if;if allowed then insert into public.session_controllers values(session,target) on conflict do nothing;else delete from public.session_controllers where session_id=session and user_id=target;end if;end$$;
create function public.new_session(b uuid,code_input text,initial jsonb) returns public.playback_sessions language plpgsql security definer set search_path=public as $$declare p public.playback_sessions;begin if not public.band_permission(b,array['owner','admin','editor']::public.band_role[]) then raise exception 'BR:Editor permission required to create a session';end if;insert into public.playback_sessions(code,band_id,leader_id,data) values(code_input,b,auth.uid(),initial) returning * into p;return p;end$$;
create function public.join_device(session uuid,device uuid,device_name text,output_role text,instrument_name text) returns public.session_devices language plpgsql security definer set search_path=public as $$declare d public.session_devices;begin if not public.session_access(session) or output_role not in ('musician','audience') then raise exception 'BR:Session access denied';end if;insert into public.session_devices(id,session_id,user_id,name,role,instrument) values(device,session,auth.uid(),left(device_name,40),output_role,left(instrument_name,30)) returning * into d;return d;end$$;
create function public.device_ready(device uuid,ready_state boolean,song uuid) returns void language plpgsql security definer set search_path=public as $$begin update public.session_devices set ready=ready_state,song_id=song,last_seen=now() where id=device and user_id=auth.uid() and public.session_access(session_id);if not found then raise exception 'BR:Device access denied';end if;end$$;
create function public.leave_device(device uuid) returns void language plpgsql security definer set search_path=public as $$begin delete from public.session_devices where id=device and user_id=auth.uid();end$$;

create function public.maintenance() returns jsonb language plpgsql security definer set search_path=public as $$declare r record;j public.processing_jobs;begin
 for r in select asset_id from public.storage_reservations where state='active' and expires_at<now() loop perform public.release_upload(r.asset_id);end loop;
 for j in select * from public.processing_jobs where status in ('queued','processing') and (created_at<now()-interval '24 hours' or status='processing' and lease_expires_at<now() and attempt>=max_attempts) for update loop update public.processing_jobs set status='expired',lease_hash=null,error='Processing expired; create a new job.',updated_at=now() where id=j.id;update public.band_usage set reserved_bytes=greatest(0,reserved_bytes-j.output_reserved_bytes) where band_id=j.band_id;update public.processing_usage set state='released' where job_id=j.id and state='reserved';end loop;
 update public.verification_tasks set status='failed',error='Verification worker timed out' where status='processing' and lease_expires_at<now() and attempt>=3;
 for r in select v.asset_id from public.verification_tasks v join public.audio_assets a on a.id=v.asset_id where v.status='failed' and a.status='pending' loop perform public.fail_input(r.asset_id,'Audio verification failed. Upload a decodable recording.');end loop;delete from public.session_devices where last_seen<now()-interval '24 hours';delete from public.playback_sessions where expires_at<now()-interval '1 day';
 delete from public.operation_events where created_at<now()-interval '30 days';delete from public.request_windows where window_start<now()-interval '2 days';
 return jsonb_build_object('ok',true,'time',now());end$$;

revoke execute on all functions in schema public from public,anon,authenticated;
grant execute on function public.band_permission(uuid,public.band_role[]),public.band_owner(uuid),public.session_access(uuid),public.session_control(uuid),public.create_band(text),public.invite_member(uuid,text,public.band_role,text),public.respond_invitation(text,boolean),public.manage_member(uuid,uuid,public.band_role),public.transfer_ownership(uuid,uuid),public.reserve_upload(uuid,uuid,uuid,uuid,text,bigint,double precision,integer,text),public.delete_asset(uuid),public.delete_band(uuid),public.replace_setlist(uuid,uuid[]),public.submit_separation(uuid,uuid,uuid,uuid,text),public.retry_separation(uuid),public.cancel_separation(uuid),public.session_mutate(text,bigint,jsonb),public.grant_control(uuid,uuid,boolean),public.new_session(uuid,text,jsonb),public.join_device(uuid,uuid,text,text,text),public.device_ready(uuid,boolean,uuid),public.leave_device(uuid) to authenticated;
grant execute on all functions in schema public to service_role;
grant select on public.verification_tasks to authenticated;
grant all on public.verification_tasks to service_role;
commit;
